INSERT INTO "mastra_messages" ("id","thread_id","content","role","type","createdAt","resourceId") VALUES ('75efbb13-7b4d-403f-87d2-ddee95bc4150','3f132823-cb61-42f9-9d97-ac2645138d80','{"format":2,"parts":[{"type":"reasoning","reasoning":"The user wants emails that look like newsletters or digests. I should search mail for newsletter-ish senders/subjects. There''s a built-in label `newsletter` — but I don''t have a tool to list emails by label. I could search mail for keywords: \"newsletter\", \"digest\", \"weekly\", \"this week\", \"unsubscribe\", \"monthly\", \"roundup\".\n\nFrom what I''ve seen: Kestrel Supply Co. \"This week at Kestrel: ...\" (many, ~30+), Codeyard \"Your weekly Codeyard digest\", Paperstack \"Your Paperstack month: ...\", Linkroom marketing, Voltaro bill (not newsletter), \"This week at the shop\".\n\nLet me run searches: \"digest\", \"weekly\", \"This week\", \"newsletter\", \"unsubscribe\", \"month\".\n\nThen compile a list with counts and mailbox. Also note the `newsletter` label exists but I can''t query by label — I could mention that.\n\nLet me do parallel searches.","details":[{"type":"text","text":"The user wants emails that look like newsletters or digests. I should search mail for newsletter-ish senders/subjects. There''s a built-in label `newsletter` — but I don''t have a tool to list emails by label. I could search mail for keywords: \"newsletter\", \"digest\", \"weekly\", \"this week\", \"unsubscribe\", \"monthly\", \"roundup\".\n\nFrom what I''ve seen: Kestrel Supply Co. \"This week at Kestrel: ...\" (many, ~30+), Codeyard \"Your weekly Codeyard digest\", Paperstack \"Your Paperstack month: ...\", Linkroom marketing, Voltaro bill (not newsletter), \"This week at the shop\".\n\nLet me run searches: \"digest\", \"weekly\", \"This week\", \"newsletter\", \"unsubscribe\", \"month\".\n\nThen compile a list with counts and mailbox. Also note the `newsletter` label exists but I can''t query by label — I could mention that.\n\nLet me do parallel searches."}],"createdAt":1794332200876},{"type":"tool-invocation","toolInvocation":{"state":"result","result":{"count":11,"emails":[{"mailboxId":"2509b3b7-2ea9-5861-9415-92dd8cc89134","mailbox":"ana@demo.trymetis.email","id":"WyJJTkJPWCIsIjEwMDAiLDM4Ml0","threadId":"<brz67yl3811n7oj@codeyard.dev>","from":"Codeyard","subject":"Your weekly Codeyard digest","date":"Mon Sep 07 2026 06:00:00 GMT+0000 (Coordinated Universal Time)","isRead":true,"isStarred":false,"snippet":""},{"mailboxId":"2509b3b7-2ea9-5861-9415-92dd8cc89134","mailbox":"ana@demo.trymetis.email","id":"WyJJTkJPWCIsIjEwMDAiLDM3Nl0","threadId":"<26cex0c013mu1e33@paperstack.app>","from":"Paperstack","subject":"Your Paperstack month: September 2026","date":"Wed Sep 02 2026 09:00:00 GMT+0000 (Coordinated Universal Time)","isRead":true,"isStarred":false,"snippet":""},{"mailboxId":"2509b3b7-2ea9-5861-9415-92dd8cc89134","mailbox":"ana@demo.trymetis.email","id":"WyJJTkJPWCIsIjEwMDAiLDM2OV0","threadId":"<1kgmlcsdyvi6qx46@codeyard.dev>","from":"Codeyard","subject":"Your weekly Codeyard digest","date":"Mon Aug 24 2026 06:00:00 GMT+0000 (Coordinated Universal Time)","isRead":true,"isStarred":false,"snippet":""},{"mailboxId":"2509b3b7-2ea9-5861-9415-92dd8cc89134","mailbox":"ana@demo.trymetis.email","id":"WyJJTkJPWCIsIjEwMDAiLDM1Ml0","threadId":"<3ypu6sfwl5ynbay4@codeyard.dev>","from":"Codeyard","subject":"Your weekly Codeyard digest","date":"Mon Jul 27 2026 06:00:00 GMT+0000 (Coordinated Universal Time)","isRead":true,"isStarred":false,"snippet":""},{"mailboxId":"2509b3b7-2ea9-5861-9415-92dd8cc89134","mailbox":"ana@demo.trymetis.email","id":"WyJJTkJPWCIsIjEwMDAiLDMzOV0","threadId":"<32otek2jw5ptv2dh@paperstack.app>","from":"Paperstack","subject":"Your Paperstack month: July 2026","date":"Thu Jul 02 2026 09:00:00 GMT+0000 (Coordinated Universal Time)","isRead":true,"isStarred":false,"snippet":""},{"mailboxId":"2509b3b7-2ea9-5861-9415-92dd8cc89134","mailbox":"ana@demo.trymetis.email","id":"WyJJTkJPWCIsIjEwMDAiLDMz